import{_ as t,o as s,c as o,a3 as a}from"./chunks/framework.D1GAkLkK.js";const u=JSON.parse('{"title":"Plugins","description":"","frontmatter":{},"headers":[],"relativePath":"plugins.md","filePath":"plugins.md"}'),d={name:"plugins.md"};function r(i,e,c,n,l,h){return s(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h1><p>The official plugins live in the <a href="https://github.com/opstruss/catalog" target="_blank" rel="noreferrer">catalog</a>, which has versions of its own. Declare it once, and each unit uses a plugin as <code>ops.&lt;name&gt;</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">uses</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ops</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">github.com/opstruss/catalog@v1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">units</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  infra</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    uses</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ops.tofu</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    with</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dir</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">./infra</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Three versions meet here: the OpsTruss that you run; the level in the <code>opstruss:</code> line of a file, the OpsTruss that the file is written for (<a href="./reference/compatibility">compatibility</a>); and <code>v1</code>, the major version of the catalog, not of OpsTruss. <code>opstruss.lock</code> pins the commit that <code>v1</code> names, one pin for every plugin of the catalog, and <code>opstruss uses update ops</code> moves them all at once. A release of the catalog may need a later OpsTruss or a later version of a tool, as its notes say; an update that needs a later OpsTruss stops with the version and keeps the pins.</p><table tabindex="0"><thead><tr><th>Plugin</th><th>What it runs</th><th>Main inputs</th></tr></thead><tbody><tr><td><a href="https://github.com/opstruss/catalog/tree/v1/plugins/tofu" target="_blank" rel="noreferrer"><code>tofu</code></a></td><td>OpenTofu root modules: an exact plan, apply, and destroy, with the state of the module kept with the state of OpsTruss</td><td><code>dir</code>, <code>vars</code>, <code>var_files</code>, <code>args</code></td></tr><tr><td><a href="https://github.com/opstruss/catalog/tree/v1/plugins/terraform" target="_blank" rel="noreferrer"><code>terraform</code></a></td><td>Terraform root modules, as <code>tofu</code> runs OpenTofu ones</td><td><code>dir</code>, <code>vars</code>, <code>var_files</code>, <code>args</code></td></tr><tr><td><a href="https://github.com/opstruss/catalog/tree/v1/plugins/compose" target="_blank" rel="noreferrer"><code>compose</code></a></td><td>Docker Compose projects, named after the unit, with <code>logs</code> and <code>config</code> tasks</td><td><code>files</code>, <code>profiles</code>, <code>env_files</code>, <code>args</code></td></tr><tr><td><a href="https://github.com/opstruss/catalog/tree/v1/plugins/brew" target="_blank" rel="noreferrer"><code>brew</code></a></td><td>Homebrew formulae and casks; <code>destroy</code> uninstalls only what the unit installed</td><td><code>packages</code>, <code>casks</code>, <code>args</code></td></tr><tr><td><a href="https://github.com/opstruss/catalog/tree/v1/plugins/apt" target="_blank" rel="noreferrer"><code>apt</code></a></td><td>Debian and Ubuntu packages, as root with <code>sudo: true</code> on the unit; <code>destroy</code> removes only what the unit installed</td><td><code>packages</code>, <code>args</code></td></tr><tr><td><a href="https://github.com/opstruss/catalog/tree/v1/plugins/dnf" target="_blank" rel="noreferrer"><code>dnf</code></a></td><td>Fedora, RHEL, and other RPM packages, as root with <code>sudo: true</code> on the unit; <code>destroy</code> removes only what the unit installed</td><td><code>packages</code>, <code>args</code></td></tr><tr><td><a href="https://github.com/opstruss/catalog/tree/v1/plugins/restic" target="_blank" rel="noreferrer"><code>restic</code></a></td><td>restic repositories, which <code>restic init</code> makes, with the tasks <code>backup</code>, <code>forget</code>, <code>check</code>, and <code>restore</code>, whose outputs later steps read</td><td><code>repository</code>, <code>password</code>, <code>credentials</code>, <code>args</code></td></tr><tr><td><a href="https://github.com/opstruss/catalog/tree/v1/plugins/vault" target="_blank" rel="noreferrer"><code>vault</code></a></td><td>No unit: the task <code>read</code> gives secrets of the key/value engine of Vault, for <code>secrets:</code></td><td><code>path</code>, <code>field</code>, <code>version</code></td></tr><tr><td><a href="https://github.com/opstruss/catalog/tree/v1/plugins/ansible" target="_blank" rel="noreferrer"><code>ansible</code></a></td><td>Ansible playbooks: a plan in check mode by host, and the data of <code>set_stats</code> as outputs</td><td><code>playbook</code>, <code>inventory</code>, <code>vars</code>, <code>limit</code>, <code>args</code></td></tr><tr><td><a href="https://github.com/opstruss/catalog/tree/v1/plugins/mise" target="_blank" rel="noreferrer"><code>mise</code></a></td><td>The tools of a mise configuration; the plan lists each tool that the machine lacks</td><td><code>dir</code>, <code>args</code></td></tr><tr><td><a href="https://github.com/opstruss/catalog/tree/v1/plugins/chezmoi" target="_blank" rel="noreferrer"><code>chezmoi</code></a></td><td>Dotfiles that chezmoi applies from a repository; the plan lists new commits and files edited by hand</td><td><code>repo</code>, <code>prompts</code>, <code>args</code></td></tr></tbody></table><p>The catalog has components too, used the same way: <a href="https://github.com/opstruss/catalog/tree/v1/components/packages" target="_blank" rel="noreferrer"><code>packages</code></a> installs one list of packages with the package manager of the machine, brew, apt, or dnf.</p><p>The README of each plugin is its documentation: its inputs, outputs, tasks, and what it needs in <code>PATH</code>. To write a plugin of your own, see <a href="./guides/writing-a-plugin">Writing a plugin</a>.</p>`,7)])])}const g=t(d,[["render",r]]);export{u as __pageData,g as default};
